import { useEffect, useMemo, useState, type ReactElement } from "react";
import type { ReportApplicationProps } from "./reportRuntime";

interface CatalogRow {
  type: string;
  parent: string;
  entity: string;
}

export function ReportApplication({ model, onVisibleDatasetsChange }: ReportApplicationProps): ReactElement {
  const [query, setQuery] = useState("");
  useEffect(() => onVisibleDatasetsChange?.(["model-catalog"]), [onVisibleDatasetsChange]);

  const dataset = model.datasets["model-catalog"];
  const rows = useMemo<CatalogRow[]>(() => (dataset?.points ?? [])
    .map((point) => ({
      type: point.dimensions[0]?.label ?? "Entity",
      parent: point.dimensions[1]?.label ?? "",
      entity: point.dimensions[2]?.label ?? point.label,
    }))
    .sort((left, right) => left.type.localeCompare(right.type)
      || left.parent.localeCompare(right.parent)
      || left.entity.localeCompare(right.entity)), [dataset]);

  const normalizedQuery = query.trim().toLowerCase();
  const visibleRows = normalizedQuery
    ? rows.filter((row) => [row.type, row.parent, row.entity].some((value) => value.toLowerCase().includes(normalizedQuery)))
    : rows;
  const counts = rows.reduce<Record<string, number>>((result, row) => {
    result[row.type] = (result[row.type] ?? 0) + 1;
    return result;
  }, {});
  const connected = rows.length > 0;

  return <main className="hello-world">
    <header className="hero">
      <div>
        <p className="eyebrow">Super Visual / connectivity proof</p>
        <h1>Hello, semantic model.</h1>
        <p className="lede">This searchable catalog arrived through the same governed semantic provider used by every Super Visual application.</p>
      </div>
      <p className={connected ? "connection connected" : "connection waiting"} role="status">
        <span aria-hidden="true" />
        {connected ? "Connected · " + rows.length + " entities" : "Waiting for semantic data…"}
      </p>
    </header>

    <section className="summary" aria-label="Semantic model summary">
      {Object.entries(counts).map(([type, count]) => <div key={type}><strong>{count}</strong><span>{type}{count === 1 ? "" : "s"}</span></div>)}
    </section>

    <section className="catalog" aria-labelledby="catalog-title">
      <div className="catalog-heading">
        <div><h2 id="catalog-title">Semantic model entities</h2><p>Tables, columns, measures, hierarchies, relationships, and parameters declared by the model.</p></div>
        <label className="search"><span>Search entities</span><input type="search" value={query} onChange={(event) => setQuery(event.currentTarget.value)} placeholder="Search type, parent, or name" /></label>
      </div>
      {!connected ? <p className="empty">The page will populate when the semantic adapter returns its first broker rows.</p>
        : visibleRows.length === 0 ? <p className="empty">No semantic entities match “{query}”.</p>
        : <div className="table-scroll"><table>
          <thead><tr><th scope="col">Type</th><th scope="col">Parent</th><th scope="col">Entity</th></tr></thead>
          <tbody>{visibleRows.map((row) => <tr key={[row.type, row.parent, row.entity].join("\u0000")}><td><span className="type">{row.type}</span></td><td>{row.parent || "—"}</td><th scope="row">{row.entity}</th></tr>)}</tbody>
        </table></div>}
    </section>
  </main>;
}

.hello-world { box-sizing: border-box; min-height: 100%; padding: 32px; color: #173c36; background: #f4f7f5; font-family: Aptos, "Segoe UI", sans-serif; }
.hello-world * { box-sizing: border-box; }
.hero { display: flex; gap: 32px; align-items: flex-start; justify-content: space-between; max-width: 1200px; margin: 0 auto; }
.eyebrow { margin: 0 0 8px; color: #167d6c; font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
.hero h1 { margin: 0; font: 600 clamp(36px, 6vw, 64px)/1 Georgia, serif; }
.lede { max-width: 720px; margin: 16px 0 0; color: #5e6d68; font-size: 17px; line-height: 1.5; }
.connection { display: inline-flex; flex: 0 0 auto; gap: 8px; align-items: center; margin: 4px 0 0; padding: 9px 13px; border: 1px solid #d3ddd8; border-radius: 999px; background: #fff; color: #5e6d68; font-size: 13px; font-weight: 700; }
.connection span { width: 9px; height: 9px; border-radius: 50%; background: #9b6b23; }
.connection.connected span { background: #2e7d5b; box-shadow: 0 0 0 3px #dcebe5; }
.summary { display: flex; flex-wrap: wrap; gap: 1px; max-width: 1200px; margin: 28px auto 0; overflow: hidden; border: 1px solid #d3ddd8; border-radius: 8px; background: #d3ddd8; }
.summary div { display: grid; min-width: 128px; flex: 1 1 128px; gap: 3px; padding: 16px 18px; background: #fff; }
.summary strong { font: 600 28px/1 Georgia, serif; }
.summary span { color: #5e6d68; font-size: 12px; }
.catalog { max-width: 1200px; margin: 18px auto 0; overflow: hidden; border: 1px solid #d3ddd8; border-radius: 8px; background: #fff; }
.catalog-heading { display: flex; gap: 24px; align-items: end; justify-content: space-between; padding: 22px 24px; border-bottom: 1px solid #d3ddd8; }
.catalog-heading h2 { margin: 0; font-size: 20px; }
.catalog-heading p { margin: 6px 0 0; color: #5e6d68; font-size: 13px; }
.search { display: grid; min-width: min(340px, 100%); gap: 6px; color: #5e6d68; font-size: 12px; font-weight: 700; }
.search input { width: 100%; padding: 10px 12px; border: 1px solid #b9c7c0; border-radius: 6px; color: #173c36; background: #fff; font: inherit; font-size: 14px; font-weight: 400; }
.search input:focus { outline: 3px solid #b8ddd5; outline-offset: 1px; border-color: #167d6c; }
.table-scroll { overflow-x: auto; }
.catalog table { width: 100%; border-collapse: collapse; text-align: left; }
.catalog th, .catalog td { padding: 13px 24px; border-bottom: 1px solid #e3eae6; }
.catalog thead th { color: #5e6d68; background: #f8faf9; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; }
.catalog tbody th { font-weight: 600; }
.catalog tbody td { color: #5e6d68; }
.catalog tbody tr:last-child th, .catalog tbody tr:last-child td { border-bottom: 0; }
.type { display: inline-block; padding: 4px 8px; border-radius: 999px; color: #126858; background: #e5f2ee; font-size: 11px; font-weight: 700; }
.empty { margin: 0; padding: 32px 24px; color: #5e6d68; }
@media (max-width: 720px) {
  .hello-world { padding: 20px; }
  .hero, .catalog-heading { align-items: stretch; flex-direction: column; }
  .search { min-width: 0; }
  .catalog th, .catalog td { padding: 12px 16px; }
}
